//! IEEE OUI vendor lookup.
//!
//! Maps the first 24, 28 or 36 bits of a MAC address to the organization the
//! IEEE assigned it to — the difference between a table full of dashes and one
//! that says "Intel Corporate" or "Apple".
//!
//! The bundled table is generated by `tools/update-oui.py` from the public IEEE
//! registry (MA-L, MA-M and MA-S) and committed, so lookups need no network
//! access. Regenerate it with that script to refresh.
//!
//! Vendor data only covers *global* addresses. A device that randomizes its MAC
//! for privacy deliberately carries no vendor information, so a miss there is
//! expected and does not mean the device is unknown to the network.

use std::collections::HashMap;
use std::sync::OnceLock;

/// The committed registry, embedded at compile time.
const OUI_DATA: &str = include_str!("../data/oui.csv");

/// Parsed registry, built on first use.
static INDEX: OnceLock<HashMap<u64, &'static str>> = OnceLock::new();

/// Look up the organization that owns a MAC address.
///
/// Accepts any of the usual spellings (`aa:bb:cc:dd:ee:ff`, `AA-BB-CC-DD-EE-FF`,
/// `aabbccddeeff`) and matches the longest assignment the registry has for the
/// address, so 28- and 36-bit assignments win over a broader 24-bit one.
pub fn lookup(mac: &str) -> Option<&'static str> {
    let hex = mac_to_hex(mac)?;
    let index = index();

    // Longest prefix first: MA-S covers 36 bits, MA-M 28, MA-L 24.
    for length in [9, 7, 6] {
        if hex.len() < length {
            continue;
        }
        if let Some(vendor) = index.get(&key(&hex[..length])) {
            return Some(vendor);
        }
    }

    None
}

/// How many assignments are bundled.
pub fn vendor_count() -> usize {
    index().len()
}

/// Build (once) the lookup table from the embedded registry.
fn index() -> &'static HashMap<u64, &'static str> {
    INDEX.get_or_init(|| {
        let mut map = HashMap::with_capacity(OUI_DATA.len() / 24);

        for line in OUI_DATA.lines() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }

            // `split_once` keeps commas that appear inside organization names.
            let Some((assignment, organization)) = line.split_once(',') else {
                continue;
            };
            if assignment.len() < 6 || assignment.len() > 9 || organization.is_empty() {
                continue;
            }
            if !assignment.bytes().all(|byte| byte.is_ascii_hexdigit()) {
                continue;
            }

            map.insert(key(assignment), organization);
        }

        map
    })
}

/// Encode an assignment with its length so 6-, 7- and 9-digit prefixes cannot
/// collide with one another.
fn key(assignment: &str) -> u64 {
    let value = u64::from_str_radix(assignment, 16).unwrap_or(0);
    ((assignment.len() as u64) << 40) | value
}

/// Normalize a MAC to uppercase hex without separators.
fn mac_to_hex(mac: &str) -> Option<String> {
    let hex: String = mac
        .chars()
        .filter(|c| c.is_ascii_hexdigit())
        .map(|c| c.to_ascii_uppercase())
        .collect();

    // A full MAC is 12 hex digits; anything shorter cannot match an assignment.
    (hex.len() >= 6).then_some(hex)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_registry_is_bundled_and_substantial() {
        // Guards against shipping an empty or truncated data file.
        assert!(
            vendor_count() > 50_000,
            "expected the full IEEE registry, found {} entries",
            vendor_count()
        );
    }

    #[test]
    fn test_known_assignments_resolve() {
        // Long-standing assignments that are unlikely to be reassigned.
        assert_eq!(lookup("00:00:0C:AA:BB:CC"), Some("Cisco Systems"));
        assert_eq!(lookup("08:00:27:12:34:56"), Some("PCS Systemtechnik")); // VirtualBox
        assert_eq!(lookup("00:50:56:AA:BB:CC"), Some("VMware"));
    }

    #[test]
    fn test_mac_spellings_are_accepted() {
        for spelling in [
            "00:00:0C:AA:BB:CC",
            "00-00-0c-aa-bb-cc",
            "0000.0caa.bbcc",
            "00000CAABBCC",
            " 00:00:0c:AA:bb:CC ",
        ] {
            assert!(
                lookup(spelling).is_some(),
                "{spelling} should resolve like 00:00:0C:AA:BB:CC"
            );
        }
    }

    #[test]
    fn test_randomized_and_unknown_macs_miss() {
        // Locally administered addresses are not in the registry by design.
        assert_eq!(lookup("A2:2D:98:D1:F6:8F"), None);
        assert_eq!(lookup("FF:FF:FF:FF:FF:FF"), None);
        assert_eq!(lookup("not a mac"), None);
        assert_eq!(lookup(""), None);
    }

    #[test]
    fn test_longest_prefix_wins() {
        // Find an assignment that exists at more than one length and confirm
        // the more specific one is preferred.
        let index = index();
        let specific = index
            .keys()
            .find(|key| (**key >> 40) == 9)
            .copied()
            .expect("registry should contain a 36-bit assignment");

        let assignment = format!("{:09X}", specific & 0xFF_FFFF_FFFF);
        let broader = &assignment[..6];

        if index.contains_key(&key(broader)) {
            assert_ne!(
                lookup(&assignment),
                index.get(&key(broader)).copied(),
                "the 36-bit assignment must win over the 24-bit one"
            );
        }
    }

    #[test]
    fn test_key_encodes_length() {
        // The same digits at different lengths must not collide.
        assert_ne!(key("AABBCC"), key("0AABBCC"));
    }
}
